namespace sv_eebbcc6cc67c466eb167de53291427f4.Services;

/// <summary>
/// Scoped service (per-circuit) that holds shared warehouse state and notifies
/// all subscribed components when that state changes.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";
    private int _lowStockCount;

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyWarehouseChanged();
        }
    }

    public int LowStockCount
    {
        get => _lowStockCount;
        set
        {
            if (_lowStockCount == value) return;
            _lowStockCount = value;
            NotifyAlertCountChanged();
        }
    }

    /// <summary>Fired when the selected warehouse changes.</summary>
    public event Action? OnWarehouseChanged;

    /// <summary>Fired when the low-stock alert count is updated.</summary>
    public event Action? OnAlertCountChanged;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } = new List<(string, string)>
    {
        ("WH-001", "Warehouse A"),
        ("WH-002", "Warehouse B"),
        ("WH-003", "Warehouse C"),
    };

    private void NotifyWarehouseChanged() => OnWarehouseChanged?.Invoke();
    private void NotifyAlertCountChanged() => OnAlertCountChanged?.Invoke();

    public void Dispose()
    {
        OnWarehouseChanged = null;
        OnAlertCountChanged = null;
    }
}

namespace sv_eebbcc6cc67c466eb167de53291427f4.Services;

/// <summary>
/// Simulates a database query returning the count of items below minimum stock levels.
/// </summary>
public sealed class InventoryAlertService
{
    private static readonly Random _random = Random.Shared;

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async database call
        int count = _random.Next(0, 16); // 0–15 inclusive
        return Task.FromResult(count);
    }
}

