@using sv_eebbcc6cc67c466eb167de53291427f4.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouseSelect" class="form-label mb-0 me-2 text-white">Site:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            style="width: auto; display: inline-block;"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        WarehouseState.CurrentWarehouseId = e.Value?.ToString() ?? "WH-001";
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= StateHasChanged;
    }
}

@using sv_eebbcc6cc67c466eb167de53291427f4.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<span class="alert-badge" title="Low stock items">
    @if (WarehouseState.LowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill">@WarehouseState.LowStockCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill">0</span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnAlertCountChanged += HandleAlertChanged;
        WarehouseState.OnWarehouseChanged += HandleAlertChanged;
    }

    private void HandleAlertChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnAlertCountChanged -= HandleAlertChanged;
        WarehouseState.OnWarehouseChanged -= HandleAlertChanged;
    }
}

