@page "/dashboard"
@rendermode InteractiveServer
@using sv_eebbcc6cc67c466eb167de53291427f4.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">
    Viewing: <strong>@GetWarehouseName(WarehouseState.CurrentWarehouseId)</strong>
</p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(WarehouseState.LowStockCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @(WarehouseState.LowStockCount > 5 ? "text-danger" : "text-success")">
                    @WarehouseState.LowStockCount
                </p>
                <p class="card-text text-muted">items below minimum level</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6">@(_isPolling ? "🟢 Active" : "⏸️ Paused")</p>
                <p class="card-text text-muted">refreshes every 10 seconds</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Last Updated</h5>
                <p class="display-6">@(_lastUpdated?.ToString("HH:mm:ss") ?? "—")</p>
                <p class="card-text text-muted">@WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private DateTime? _lastUpdated;

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
        WarehouseState.OnAlertCountChanged += HandleAlertChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await StartPollingAsync();
        }
    }

    private async void HandleWarehouseChanged()
    {
        // Restart polling immediately for the new warehouse
        StopPolling();
        await InvokeAsync(async () =>
        {
            await StartPollingAsync();
            StateHasChanged();
        });
    }

    private void HandleAlertChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private async Task StartPollingAsync()
    {
        _cts = new CancellationTokenSource();
        _isPolling = true;

        // Immediately fetch and then poll every 10 seconds
        await PollOnceAsync();
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken token)
    {
        try
        {
            using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            while (await timer.WaitForNextTickAsync(token))
            {
                await PollOnceAsync();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task PollOnceAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        _lastUpdated = DateTime.Now;

        // Setting LowStockCount fires OnAlertCountChanged, which notifies ALL subscribers
        // (sidebar badge, this page, any other component listening)
        WarehouseState.LowStockCount = count;
        await InvokeAsync(StateHasChanged);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _isPolling = false;
    }

    private static string GetWarehouseName(string id)
    {
        return WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == id).Name ?? id;
    }

    public void Dispose()
    {
        StopPolling();
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        WarehouseState.OnAlertCountChanged -= HandleAlertChanged;
    }
}

